insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Tribunal Constitucional (Título IX CE y LOTC)"},{"n":"1.1","title":"Naturaleza y composición (arts. 159 CE; 1 y 5 LOTC)"},{"n":"1.2","title":"Presidente y mandato (art. 160 CE; art. 9 LOTC)"},{"n":"1.3","title":"Competencias (art. 161 CE; art. 2 LOTC)"},{"n":"1.4","title":"Legitimación y sentencias (arts. 162-164 CE)"},{"n":"2","title":"La reforma de la Constitución (Título X)"},{"n":"2.1","title":"Procedimiento ordinario (art. 167)"},{"n":"2.2","title":"Procedimiento agravado y límites (arts. 168-169)"},{"n":"3","title":"La Corona (Título II)"},{"n":"3.1","title":"El Rey: posición y funciones constitucionales (arts. 56, 62-63)"},{"n":"3.2","title":"El refrendo (art. 64)"},{"n":"3.3","title":"Sucesión (art. 57)"},{"n":"3.4","title":"Regencia y tutela (arts. 59-60)"}]'::jsonb, '["Art. 1.1 LOTC: «El Tribunal Constitucional, como intérprete supremo de la Constitución, es independiente de los demás órganos constitucionales y está sometido sólo a la Constitución y a la presente Ley Orgánica.»","Art. 159.1 CE: «El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey; de ellos, cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.»","Art. 159.3 CE: «Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres.»","Art. 160 CE: «El Presidente del Tribunal Constitucional será nombrado entre sus miembros por el Rey, a propuesta del mismo Tribunal en pleno y por un período de tres años.»","Art. 162.1 CE: «Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso, las Asambleas de las mismas.»","Art. 164.1 CE: «Las sentencias del Tribunal Constitucional se publicarán en el boletín oficial del Estado con los votos particulares, si los hubiere. Tienen el valor de cosa juzgada a partir del día siguiente de su publicación y no cabe recurso alguno contra ellas.»","Art. 167.1 CE: «Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras.»","Art. 168.1 CE: «Cuando se propusiere la revisión total de la Constitución o una parcial que afecte al Título preliminar, al Capítulo segundo, Sección primera del Título I, o al Título II, se procederá a la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes.»","Art. 169 CE: «No podrá iniciarse la reforma constitucional en tiempo de guerra o de vigencia de alguno de los estados previstos en el artículo 116.»","Art. 56.1 CE: «El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones»","Art. 56.3 CE: «La persona del Rey es inviolable y no está sujeta a responsabilidad.»","Art. 64.1 CE: «La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso.»","Art. 64.2 CE: «De los actos del Rey serán responsables las personas que los refrenden.»","Art. 57.1 CE: «La sucesión en el trono seguirá el orden regular de primogenitura y representación, siendo preferida siempre la línea anterior a las posteriores; en la misma línea, el grado más próximo al más remoto; en el mismo grado, el varón a la mujer, y en el mismo sexo, la persona de más edad a la de menos.»","Art. 59.3 CE: «Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales, y se compondrá de una, tres o cinco personas.»","Art. 59.5 CE: «La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: LOTC (https://www.boe.es/buscar/act.php?id=BOE-A-1979-23709)'
