insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b1-03-cortes-defensor' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Las Cortes Generales: naturaleza y funciones (art. 66)"},{"n":"2","title":"El Congreso de los Diputados: composición y elección (art. 68)"},{"n":"3","title":"El Senado: composición y elección (art. 69)"},{"n":"4","title":"Estatuto de los parlamentarios (arts. 67, 70-71)"},{"n":"5","title":"Funcionamiento de las Cámaras (arts. 72-80)"},{"n":"5.1","title":"Reglamentos, períodos de sesiones y sesiones conjuntas"},{"n":"5.2","title":"Pleno, Comisiones y Diputación Permanente"},{"n":"5.3","title":"Quórum y mayorías"},{"n":"6","title":"Atribuciones: elaboración de las leyes y tratados (arts. 81-96)"},{"n":"7","title":"El Defensor del Pueblo (art. 54 CE y LO 3/1981)"},{"n":"7.1","title":"Elección, mandato y cese"},{"n":"7.2","title":"Prerrogativas e incompatibilidades; Adjuntos"},{"n":"7.3","title":"Quejas e informe a las Cortes"}]'::jsonb, '["Art. 66.2 CE: «Las Cortes Generales ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno y tienen las demás competencias que les atribuya la Constitución.»","Art. 68.1 CE: «El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados, elegidos por sufragio universal, libre, igual, directo y secreto, en los términos que establezca la ley.»","Art. 68.4 CE: «El Congreso es elegido por cuatro años. El mandato de los Diputados termina cuatro años después de su elección o el día de la disolución de la Cámara.»","Art. 69.1 CE: «El Senado es la Cámara de representación territorial.»","Art. 69.5 CE: «Las Comunidades Autónomas designarán además un Senador y otro más por cada millón de habitantes de su respectivo territorio.»","Art. 71.3 CE: «En las causas contra Diputados y Senadores será competente la Sala de lo Penal del Tribunal Supremo.»","Art. 73.1 CE: «Las Cámaras se reunirán anualmente en dos períodos ordinarios de sesiones: el primero, de septiembre a diciembre, y el segundo, de febrero a junio.»","Art. 78.1 CE: «En cada Cámara habrá una Diputación Permanente compuesta por un mínimo de veintiún miembros, que representarán a los grupos parlamentarios, en proporción a su importancia numérica.»","Art. 79.3 CE: «El voto de Senadores y Diputados es personal e indelegable.»","Art. 81.2 CE: «La aprobación, modificación o derogación de las leyes orgánicas exigirá mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.»","Art. 90.2 CE: «El Senado en el plazo de dos meses, a partir del día de la recepción del texto, puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo. El veto deberá ser aprobado por mayoría absoluta.»","Art. 54 CE: «Una ley orgánica regulará la institución del Defensor del Pueblo, como alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en este Título, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.»","Art. 2.1 LO 3/1981: «El Defensor del Pueblo será elegido por las Cortes Generales para un periodo de cinco años»","Art. 2.4 LO 3/1981: «Será designado quien obtuviese una votación favorable de las tres quintas partes de los miembros del Congreso y posteriormente, en un plazo máximo de veinte días, fuese ratificado por esta misma mayoría del Senado.»","Art. 6.1 LO 3/1981: «El Defensor del Pueblo no estará sujeto a mandato imperativo alguno. No recibirá instrucciones de ninguna Autoridad. Desempeñará sus funciones con autonomía y según su criterio.»","Art. 32.1 LO 3/1981: «El Defensor del Pueblo dará cuenta anualmente a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas cuando se hallen reunidas en periodo ordinario de sesiones.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: LO 3/1981 (https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325)'
