insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b1-04-poder-judicial' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Poder Judicial en la Constitución (Título VI)"},{"n":"1.1","title":"Principios: independencia, unidad jurisdiccional y exclusividad (art. 117)"},{"n":"1.2","title":"Gratuidad, publicidad, oralidad y responsabilidad del Estado (arts. 118-121)"},{"n":"1.3","title":"Ministerio Fiscal, participación ciudadana e incompatibilidades (arts. 124-127)"},{"n":"2","title":"El Consejo General del Poder Judicial"},{"n":"2.1","title":"Naturaleza y composición (art. 122 CE; arts. 558, 566-568 LOPJ)"},{"n":"2.2","title":"Presidente y órganos: Pleno y Comisiones (arts. 586-602 LOPJ)"},{"n":"3","title":"El Tribunal Supremo (art. 123 CE; arts. 53-61 LOPJ)"},{"n":"4","title":"La organización judicial española"},{"n":"4.1","title":"División territorial (art. 30 LOPJ)"},{"n":"4.2","title":"Audiencia Nacional (arts. 62-69 LOPJ)"},{"n":"4.3","title":"Tribunales Superiores de Justicia (arts. 70-72 LOPJ)"},{"n":"4.4","title":"Audiencias Provinciales y Jueces de Paz (arts. 80, 99-101 LOPJ)"}]'::jsonb, '["Art. 117.1 CE: «La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.»","Art. 117.3 CE: «El ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes, según las normas de competencia y procedimiento que las mismas establezcan.»","Art. 117.5 CE: «El principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales.»","Art. 119 CE: «La justicia será gratuita cuando así lo disponga la ley y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar.»","Art. 120.3 CE: «Las sentencias serán siempre motivadas y se pronunciarán en audiencia pública.»","Art. 121 CE: «Los daños causados por error judicial, así como los que sean consecuencia del funcionamiento anormal de la Administración de Justicia, darán derecho a una indemnización a cargo del Estado, conforme a la ley.»","Art. 124.4 CE: «El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial.»","Art. 122.2 CE: «El Consejo General del Poder Judicial es el órgano de gobierno del mismo.»","Art. 122.3 CE: «El Consejo General del Poder Judicial estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte miembros nombrados por el Rey por un período de cinco años.»","Art. 566 LOPJ: «El Consejo General del Poder Judicial estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte Vocales, de los cuales doce serán Jueces o Magistrados en servicio activo en la carrera judicial y ocho juristas de reconocida competencia.»","Art. 586.3 LOPJ: «La elección tendrá lugar en una sesión a celebrar entre tres y siete días más tarde, siendo elegido quien en votación nominal obtenga el apoyo de la mayoría de tres quintos de los miembros del Pleno.»","Art. 123 CE: «El Tribunal Supremo, con jurisdicción en toda España, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales. […] El Presidente del Tribunal Supremo será nombrado por el Rey, a propuesta del Consejo General del Poder Judicial, en la forma que determine la ley.»","Art. 53 LOPJ: «El Tribunal Supremo, con sede en la villa de Madrid, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías Constitucionales. Tendrá jurisdicción en toda España y ningún otro podrá tener el título de Supremo.»","Art. 30 LOPJ: «El Estado se organiza territorialmente, a efectos judiciales, en Municipios, Partidos, Provincias y Comunidades Autónomas.»","Art. 62 LOPJ: «La Audiencia Nacional, con sede en la villa de Madrid, tiene jurisdicción en toda España.»","Art. 70 LOPJ: «El Tribunal Superior de Justicia de la Comunidad Autónoma culminará la organización judicial en el ámbito territorial de aquélla, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: LOPJ (https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666)'
