insert into public.topics (slug, title) values ('age-aux-b1-05-gobierno', 'I.5 El Gobierno y la Administración') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b1-05-gobierno' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Gobierno: funciones y composición (arts. 97-98 CE; arts. 1-4 LG)"},{"n":"1.1","title":"Funciones del Gobierno (art. 97 CE; art. 1 LG)"},{"n":"1.2","title":"Composición y estatuto de sus miembros (art. 98 CE; arts. 11-14 LG)"},{"n":"2","title":"El Presidente del Gobierno (art. 98.2 CE; arts. 2 y 13 LG)"},{"n":"3","title":"El Consejo de Ministros y las Comisiones Delegadas (arts. 5, 6 y 18 LG)"},{"n":"4","title":"Órganos de colaboración y apoyo (arts. 7-10 LG)"},{"n":"5","title":"Designación del Presidente y de los demás miembros (arts. 99-100 CE; art. 12 LG)"},{"n":"6","title":"Causas de cese y Gobierno en funciones (art. 101 CE; art. 21 LG)"},{"n":"7","title":"Responsabilidad del Gobierno (arts. 102 y 108-115 CE)"},{"n":"7.1","title":"Responsabilidad criminal (art. 102 CE)"},{"n":"7.2","title":"Responsabilidad política: cuestión de confianza y moción de censura (arts. 108, 112-114 CE)"},{"n":"7.3","title":"Disolución de las Cámaras (art. 115 CE)"}]'::jsonb, '["Art. 97 CE: «El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado. Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.»","Art. 98.1 CE: «El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley.»","Art. 11 Ley 50/1997: «Para ser miembro del Gobierno se requiere ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo, así como no estar inhabilitado para ejercer empleo o cargo público por sentencia judicial firme»","Art. 98.2 CE: «El Presidente dirige la acción del Gobierno y coordina las funciones de los demás miembros del mismo, sin perjuicio de la competencia y responsabilidad directa de éstos en su gestión.»","Art. 13.1 Ley 50/1997: «En los casos de vacante, ausencia o enfermedad, las funciones del Presidente del Gobierno serán asumidas por los Vicepresidentes, de acuerdo con el correspondiente orden de prelación, y, en defecto de ellos, por los Ministros, según el orden de precedencia de los Departamentos.»","Art. 18.1 Ley 50/1997: «El Presidente del Gobierno convoca y preside las reuniones del Consejo de Ministros, actuando como Secretario el Ministro de la Presidencia.»","Art. 5.3 Ley 50/1997: «Las deliberaciones del Consejo de Ministros serán secretas.»","Art. 7.1 Ley 50/1997: «Los Secretarios de Estado son órganos superiores de la Administración General del Estado, directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica de un Departamento o de la Presidencia del Gobierno.»","Art. 99.3 CE: «Si el Congreso de los Diputados, por el voto de la mayoría absoluta de sus miembros, otorgare su confianza a dicho candidato, el Rey le nombrará Presidente. De no alcanzarse dicha mayoría, se someterá la misma propuesta a nueva votación cuarenta y ocho horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple.»","Art. 100 CE: «Los demás miembros del Gobierno serán nombrados y separados por el Rey, a propuesta de su Presidente.»","Art. 101 CE: «El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente. 2. El Gobierno cesante continuará en funciones hasta la toma de posesión del nuevo Gobierno.»","Art. 21.3 Ley 50/1997: «El Gobierno en funciones facilitará el normal desarrollo del proceso de formación del nuevo Gobierno y el traspaso de poderes al mismo y limitará su gestión al despacho ordinario de los asuntos públicos»","Art. 102.1 CE: «La responsabilidad criminal del Presidente y los demás miembros del Gobierno será exigible, en su caso, ante la Sala de lo Penal del Tribunal Supremo.»","Art. 108 CE: «El Gobierno responde solidariamente en su gestión política ante el Congreso de los Diputados.»","Art. 113.1-2 CE: «El Congreso de los Diputados puede exigir la responsabilidad política del Gobierno mediante la adopción por mayoría absoluta de la moción de censura. 2. La moción de censura deberá ser propuesta al menos por la décima parte de los Diputados, y habrá de incluir un candidato a la Presidencia del Gobierno.»","Art. 115.1 CE: «El Presidente del Gobierno, previa deliberación del Consejo de Ministros, y bajo su exclusiva responsabilidad, podrá proponer la disolución del Congreso, del Senado o de las Cortes Generales, que será decretada por el Rey.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: Ley 50/1997 (https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336)'
