insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-aux-b1-07-transparencia', 'I.7 La Ley 19/2013 de transparencia, acceso a la información pública y buen gobierno') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b1-07-transparencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Objeto de la Ley 19/2013 (art. 1)"},{"n":"2","title":"Transparencia: ámbito subjetivo (arts. 2-4)"},{"n":"3","title":"Publicidad activa (arts. 5-11)"},{"n":"3.1","title":"Obligaciones de publicación (arts. 5-8)"},{"n":"3.2","title":"Control y Portal de la Transparencia (arts. 9-11)"},{"n":"4","title":"Derecho de acceso a la información pública (arts. 12-24)"},{"n":"4.1","title":"Titulares, concepto y límites (arts. 12-16)"},{"n":"4.2","title":"Solicitud, tramitación y resolución (arts. 17-22)"},{"n":"4.3","title":"Reclamación ante el Consejo de Transparencia y Buen Gobierno (arts. 23-24)"},{"n":"5","title":"Buen gobierno: principios, infracciones y sanciones (arts. 25-32)"},{"n":"6","title":"El Consejo de Transparencia y Buen Gobierno (arts. 33-40)"}]'::jsonb, '["Art. 1 Ley 19/2013: «Esta Ley tiene por objeto ampliar y reforzar la transparencia de la actividad pública, regular y garantizar el derecho de acceso a la información relativa a aquella actividad y establecer las obligaciones de buen gobierno que deben cumplir los responsables públicos así como las consecuencias derivadas de su incumplimiento.»","Art. 3.b) Ley 19/2013: «Las entidades privadas que perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 100.000 euros o cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros.»","Art. 5.1 Ley 19/2013: «Los sujetos enumerados en el artículo 2.1 publicarán de forma periódica y actualizada la información cuyo conocimiento sea relevante para garantizar la transparencia de su actividad relacionada con el funcionamiento y control de la actuación pública.»","Art. 9.3 Ley 19/2013: «El incumplimiento reiterado de las obligaciones de publicidad activa reguladas en este capítulo tendrá la consideración de infracción grave a los efectos de aplicación a sus responsables del régimen disciplinario previsto en la correspondiente normativa reguladora.»","Art. 10.1 Ley 19/2013: «La Administración General del Estado desarrollará un Portal de la Transparencia, dependiente del Ministerio de la Presidencia, que facilitará el acceso de los ciudadanos a toda la información a la que se refieren los artículos anteriores relativa a su ámbito de actuación.»","Art. 12 Ley 19/2013: «Todas las personas tienen derecho a acceder a la información pública, en los términos previstos en el artículo 105.b) de la Constitución Española, desarrollados por esta Ley.»","Art. 13 Ley 19/2013: «Se entiende por información pública los contenidos o documentos, cualquiera que sea su formato o soporte, que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de este título y que hayan sido elaborados o adquiridos en el ejercicio de sus funciones.»","Art. 17.3 Ley 19/2013: «El solicitante no está obligado a motivar su solicitud de acceso a la información.»","Art. 20.1 Ley 19/2013: «La resolución en la que se conceda o deniegue el acceso deberá notificarse al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de un mes desde la recepción de la solicitud por el órgano competente para resolver. Este plazo podrá ampliarse por otro mes en el caso de que el volumen o la complejidad de la información que se solicita así lo hagan necesario y previa notificación al solicitante.»","Art. 20.4 Ley 19/2013: «Transcurrido el plazo máximo para resolver sin que se haya dictado y notificado resolución expresa se entenderá que la solicitud ha sido desestimada.»","Art. 22.4 Ley 19/2013: «El acceso a la información será gratuito.»","Art. 24.1 Ley 19/2013: «Frente a toda resolución expresa o presunta en materia de acceso podrá interponerse una reclamación ante el Consejo de Transparencia y Buen Gobierno, con carácter potestativo y previo a su impugnación en vía contencioso-administrativa.»","Art. 24.4 Ley 19/2013: «El plazo máximo para resolver y notificar la resolución será de tres meses, transcurrido el cual, la reclamación se entenderá desestimada.»","Art. 32.1 Ley 19/2013: «El plazo de prescripción de las infracciones previstas en este título será de cinco años para las infracciones muy graves, tres años para las graves y un año para las leves.»","Art. 33.2 Ley 19/2013: «El Consejo de Transparencia y Buen Gobierno tiene personalidad jurídica propia y plena capacidad de obrar. Actúa con autonomía y plena independencia en el cumplimiento de sus fines.»","Art. 37.1 Ley 19/2013: «El Presidente del Consejo de Transparencia y Buen Gobierno será nombrado por un período no renovable de cinco años mediante Real Decreto»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887', null, null, null, null
