insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Régimen jurídico: objeto y ámbito de la LO 3/2018 (arts. 1-3)"},{"n":"2","title":"Principios de protección de datos (arts. 4-10)"},{"n":"2.1","title":"Exactitud y confidencialidad (arts. 4-5)"},{"n":"2.2","title":"Consentimiento y consentimiento de menores (arts. 6-7)"},{"n":"2.3","title":"Otras bases jurídicas y categorías especiales de datos (arts. 8-10)"},{"n":"3","title":"Derechos de las personas: transparencia e información (art. 11)"},{"n":"4","title":"Ejercicio de los derechos: acceso, rectificación, supresión, limitación, portabilidad y oposición (arts. 12-18)"},{"n":"5","title":"Tratamientos concretos: la videovigilancia (art. 22)"},{"n":"6","title":"Obligaciones del responsable y del encargado: responsabilidad activa, registro y bloqueo (arts. 28-33)"},{"n":"7","title":"El delegado de protección de datos (arts. 34-37)"},{"n":"8","title":"La Agencia Española de Protección de Datos (arts. 44-48)"},{"n":"9","title":"Régimen sancionador: prescripción de las infracciones (arts. 72-74)"}]'::jsonb, '["Art. 1 LO 3/2018: «El derecho fundamental de las personas físicas a la protección de datos personales, amparado por el artículo 18.4 de la Constitución, se ejercerá con arreglo a lo establecido en el Reglamento (UE) 2016/679 y en esta ley orgánica.»","Art. 5.1 LO 3/2018: «Los responsables y encargados del tratamiento de datos así como todas las personas que intervengan en cualquier fase de este estarán sujetas al deber de confidencialidad al que se refiere el artículo 5.1.f) del Reglamento (UE) 2016/679.»","Art. 6.1 LO 3/2018: «De conformidad con lo dispuesto en el artículo 4.11 del Reglamento (UE) 2016/679, se entiende por consentimiento del afectado toda manifestación de voluntad libre, específica, informada e inequívoca por la que este acepta, ya sea mediante una declaración o una clara acción afirmativa, el tratamiento de datos personales que le conciernen.»","Art. 7 LO 3/2018: «El tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea mayor de catorce años. […] El tratamiento de los datos de los menores de catorce años, fundado en el consentimiento, solo será lícito si consta el del titular de la patria potestad o tutela, con el alcance que determinen los titulares de la patria potestad o tutela.»","Art. 9.1 LO 3/2018: «A los efectos del artículo 9.2.a) del Reglamento (UE) 2016/679, a fin de evitar situaciones discriminatorias, el solo consentimiento del afectado no bastará para levantar la prohibición del tratamiento de datos cuya finalidad principal sea identificar su ideología, afiliación sindical, religión, orientación sexual, creencias u origen racial o étnico.»","Art. 11.2 LO 3/2018: «La información básica a la que se refiere el apartado anterior deberá contener, al menos: a) La identidad del responsable del tratamiento y de su representante, en su caso. b) La finalidad del tratamiento. c) La posibilidad de ejercer los derechos establecidos en los artículos 15 a 22 del Reglamento (UE) 2016/679.»","Art. 12.1 LO 3/2018: «Los derechos reconocidos en los artículos 15 a 22 del Reglamento (UE) 2016/679, podrán ejercerse directamente o por medio de representante legal o voluntario.»","Art. 12.7 LO 3/2018: «Serán gratuitas las actuaciones llevadas a cabo por el responsable del tratamiento para atender las solicitudes de ejercicio de estos derechos»","Art. 13.3 LO 3/2018: «A los efectos establecidos en el artículo 12.5 del Reglamento (UE) 2016/679 se podrá considerar repetitivo el ejercicio del derecho de acceso en más de una ocasión durante el plazo de seis meses, a menos que exista causa legítima para ello.»","Art. 22.3 LO 3/2018: «Los datos serán suprimidos en el plazo máximo de un mes desde su captación, salvo cuando hubieran de ser conservados para acreditar la comisión de actos que atenten contra la integridad de personas, bienes o instalaciones. En tal caso, las imágenes deberán ser puestas a disposición de la autoridad competente en un plazo máximo de setenta y dos horas desde que se tuviera conocimiento de la existencia de la grabación.»","Art. 32.1 LO 3/2018: «El responsable del tratamiento estará obligado a bloquear los datos cuando proceda a su rectificación o supresión.»","Art. 34.3 LO 3/2018: «Los responsables y encargados del tratamiento comunicarán en el plazo de diez días a la Agencia Española de Protección de Datos o, en su caso, a las autoridades autonómicas de protección de datos, las designaciones, nombramientos y ceses de los delegados de protección de datos»","Art. 36.2 LO 3/2018: «el delegado de protección de datos no podrá ser removido ni sancionado por el responsable o el encargado por desempeñar sus funciones salvo que incurriera en dolo o negligencia grave en su ejercicio.»","Art. 44.1 LO 3/2018: «La Agencia Española de Protección de Datos es una autoridad administrativa independiente de ámbito estatal, de las previstas en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, con personalidad jurídica y plena capacidad pública y privada, que actúa con plena independencia de los poderes públicos en el ejercicio de sus funciones.»","Art. 48.5 LO 3/2018: «El mandato de la Presidencia y del Adjunto de la Agencia Española de Protección de Datos tiene una duración de cinco años y puede ser renovado para otro período de igual duración.»","Arts. 72-74 LO 3/2018: «se consideran muy graves y prescribirán a los tres años […] se consideran graves y prescribirán a los dos años […] Se consideran leves y prescribirán al año»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673', null, null, null, null
  from public.topics t where t.slug = 'age-aux-b1-12-proteccion-datos'
