insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El personal al servicio de las Administraciones públicas: concepto y clases (arts. 8-13)"},{"n":"1.1","title":"Funcionarios de carrera e interinos (arts. 9-10)"},{"n":"1.2","title":"Personal laboral, eventual y directivo (arts. 11-13)"},{"n":"2","title":"Selección y adquisición de la condición de funcionario (arts. 55-62)"},{"n":"2.1","title":"Principios rectores y requisitos generales (arts. 55-59)"},{"n":"2.2","title":"Órganos, sistemas selectivos y adquisición de la condición (arts. 60-62)"},{"n":"3","title":"Programación de efectivos y Oferta de Empleo Público (arts. 69-70)"},{"n":"4","title":"Grupos de clasificación profesional (art. 76)"},{"n":"5","title":"Provisión de puestos de trabajo y movilidad (arts. 78-84)"},{"n":"6","title":"Situaciones administrativas de los funcionarios (arts. 85-92)"},{"n":"6.1","title":"Servicios especiales y servicio en otras Administraciones (arts. 87-88)"},{"n":"6.2","title":"Excedencia y suspensión de funciones (arts. 89-90)"}]'::jsonb, '["Art. 8.1 TREBEP: «Son empleados públicos quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales.»","Art. 9.1 TREBEP: «Son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.»","Art. 10.1.d) TREBEP: «El exceso o acumulación de tareas por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses.»","Art. 12.1 TREBEP: «Es personal eventual el que, en virtud de nombramiento y con carácter no permanente, sólo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a los créditos presupuestarios consignados para este fin.»","Art. 56.1.c) TREBEP: «Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa.»","Art. 59.1 TREBEP: «En las ofertas de empleo público se reservará un cupo no inferior al siete por ciento de las vacantes para ser cubiertas entre personas con discapacidad»","Art. 60.2 TREBEP: «El personal de elección o de designación política, los funcionarios interinos y el personal eventual no podrán formar parte de los órganos de selección.»","Art. 61.6 TREBEP: «Los sistemas selectivos de funcionarios de carrera serán los de oposición y concurso-oposición que deberán incluir, en todo caso, una o varias pruebas para determinar la capacidad de los aspirantes y establecer el orden de prelación.»","Art. 62.1 TREBEP: «La condición de funcionario de carrera se adquiere por el cumplimiento sucesivo de los siguientes requisitos: a) Superación del proceso selectivo. b) Nombramiento por el órgano o autoridad competente, que será publicado en el Diario Oficial correspondiente. c) Acto de acatamiento de la Constitución y, en su caso, del Estatuto de Autonomía correspondiente y del resto del Ordenamiento Jurídico. d) Toma de posesión dentro del plazo que se establezca.»","Art. 70.1 TREBEP: «En todo caso, la ejecución de la oferta de empleo público o instrumento similar deberá desarrollarse dentro del plazo improrrogable de tres años.»","Art. 70.2 TREBEP: «La Oferta de empleo público o instrumento similar, que se aprobará anualmente por los órganos de Gobierno de las Administraciones Públicas, deberá ser publicada en el Diario oficial correspondiente.»","Art. 78.2 TREBEP: «La provisión de puestos de trabajo en cada Administración Pública se llevará a cabo por los procedimientos de concurso y de libre designación con convocatoria pública.»","Art. 85.1 TREBEP: «Los funcionarios de carrera se hallarán en alguna de las siguientes situaciones: a) Servicio activo. b) Servicios especiales. c) Servicio en otras Administraciones Públicas. d) Excedencia. e) Suspensión de funciones.»","Art. 89.1 TREBEP: «La excedencia de los funcionarios de carrera podrá adoptar las siguientes modalidades: a) Excedencia voluntaria por interés particular. b) Excedencia voluntaria por agrupación familiar. c) Excedencia por cuidado de familiares. d) Excedencia por razón de violencia de género o de violencia sexual. e) Excedencia por razón de violencia terrorista.»","Art. 89.4 TREBEP: «El puesto de trabajo desempeñado se reservará, al menos, durante dos años. Transcurrido este periodo, dicha reserva lo será a un puesto en la misma localidad y de igual retribución.»","Art. 90.1 TREBEP: «La suspensión determinará la pérdida del puesto de trabajo cuando exceda de seis meses.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', null, null, null, null
