insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Derechos de los empleados públicos (arts. 14-15)"},{"n":"2","title":"La carrera administrativa y la evaluación del desempeño (arts. 16-17 y 19-20)"},{"n":"3","title":"Promoción interna (art. 18)"},{"n":"4","title":"El sistema de retribuciones e indemnizaciones (arts. 21-30)"},{"n":"4.1","title":"Retribuciones básicas y complementarias (arts. 22-24)"},{"n":"4.2","title":"Interinos, funcionarios en prácticas, indemnizaciones y deducciones (arts. 25-30)"},{"n":"5","title":"Negociación colectiva, representación y reunión (arts. 31-46)"},{"n":"6","title":"Jornada, permisos y vacaciones (arts. 47-51)"},{"n":"7","title":"Deberes y Código de Conducta (arts. 52-54)"},{"n":"8","title":"Régimen disciplinario (arts. 93-98)"},{"n":"8.1","title":"Faltas y sanciones (arts. 95-96)"},{"n":"8.2","title":"Prescripción y procedimiento (arts. 97-98)"}]'::jsonb, '["Art. 14.a) TREBEP: «A la inamovilidad en la condición de funcionario de carrera.»","Art. 16.2 TREBEP: «La carrera profesional es el conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional conforme a los principios de igualdad, mérito y capacidad.»","Art. 16.3.c) TREBEP: «Promoción interna vertical, que consiste en el ascenso desde un cuerpo o escala de un Subgrupo, o Grupo de clasificación profesional en el supuesto de que éste no tenga Subgrupo, a otro superior, de acuerdo con lo establecido en el artículo 18.»","Art. 18.2 TREBEP: «Los funcionarios deberán poseer los requisitos exigidos para el ingreso, tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo, o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo y superar las correspondientes pruebas selectivas.»","Art. 22.1 TREBEP: «Las retribuciones de los funcionarios de carrera se clasifican en básicas y complementarias.»","Art. 22.4 TREBEP: «Las pagas extraordinarias serán dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las retribuciones complementarias, salvo aquéllas a las que se refieren los apartados c) y d) del artículo 24.»","Art. 23.b) TREBEP: «Los trienios, que consisten en una cantidad, que será igual para cada Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo, por cada tres años de servicio.»","Art. 28 TREBEP: «Los funcionarios percibirán las indemnizaciones correspondientes por razón del servicio.»","Art. 42 TREBEP: «El mandato de los miembros de las Juntas de Personal y de los Delegados de Personal, en su caso, será de cuatro años, pudiendo ser reelegidos.»","Art. 50.1 TREBEP: «Los funcionarios públicos tendrán derecho a disfrutar, durante cada año natural, de unas vacaciones retribuidas de veintidós días hábiles, o de los días que correspondan proporcionalmente si el tiempo de servicio durante el año fue menor.»","Art. 54.3 TREBEP: «Obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico, en cuyo caso las pondrán inmediatamente en conocimiento de los órganos de inspección procedentes.»","Art. 95.1 TREBEP: «Las faltas disciplinarias pueden ser muy graves, graves y leves.»","Art. 96.1.c) TREBEP: «Suspensión firme de funciones, o de empleo y sueldo en el caso del personal laboral, con una duración máxima de 6 años.»","Art. 97.1 TREBEP: «Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año.»","Art. 98.2 TREBEP: «En el procedimiento quedará establecida la debida separación entre la fase instructora y la sancionadora, encomendándose a órganos distintos.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', null, null, null, null
