insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-aux-b1-16-igualdad', 'I.16 Igualdad, violencia de género, LGTBI, discapacidad y dependencia') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug = 'auxiliar-administrativo-estado' and t.slug = 'age-aux-b1-16-igualdad' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Políticas de igualdad entre mujeres y hombres (LO 3/2007)"},{"n":"1.1","title":"Principio de igualdad y tutela contra la discriminación (arts. 1-13)"},{"n":"1.2","title":"Igualdad en el empleo privado y público (arts. 45-64; disp. adic. 1.ª)"},{"n":"2","title":"Políticas contra la violencia de género (LO 1/2004)"},{"n":"2.1","title":"Objeto y derechos de las funcionarias víctimas (arts. 1 y 24-26)"},{"n":"2.2","title":"Tutela institucional (arts. 29-30)"},{"n":"3","title":"Igualdad de trato y no discriminación de las personas LGTBI (Ley 4/2023)"},{"n":"3.1","title":"Definiciones y rectificación registral de la mención relativa al sexo (arts. 3 y 43-47)"},{"n":"4","title":"Discapacidad: régimen jurídico (RDL 1/2013)"},{"n":"5","title":"Dependencia: régimen jurídico (Ley 39/2006)"}]'::jsonb, '["Art. 6.1 LO 3/2007: «Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.»","Art. 7.3 LO 3/2007: «Se considerarán en todo caso discriminatorios el acoso sexual y el acoso por razón de sexo.»","Art. 45.2 LO 3/2007: «En el caso de las empresas de cincuenta o más trabajadores, las medidas de igualdad a que se refiere el apartado anterior deberán dirigirse a la elaboración y aplicación de un plan de igualdad»","Disp. adic. 1.ª LO 3/2007: «A los efectos de esta Ley, se entenderá por composición equilibrada la presencia de mujeres y hombres de forma que, en el conjunto a que se refiera, las personas de cada sexo no superen el sesenta por ciento ni sean menos del cuarenta por ciento.»","Art. 1.1 LO 1/2004: «La presente Ley tiene por objeto actuar contra la violencia que, como manifestación de la discriminación, la situación de desigualdad y las relaciones de poder de los hombres sobre las mujeres, se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.»","Art. 24 LO 1/2004: «La funcionaria víctima de violencia de género tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia en los términos que se determinen en su legislación específica.»","Art. 30.2 LO 1/2004: «El Observatorio Estatal de Violencia sobre la Mujer remitirá al Gobierno y a las Comunidades Autónomas, con periodicidad anual, un informe sobre la evolución de la violencia ejercida sobre la mujer»","Art. 3.k) Ley 4/2023: «Persona trans: Persona cuya identidad sexual no se corresponde con el sexo asignado al nacer.»","Art. 43.1 Ley 4/2023: «Toda persona de nacionalidad española mayor de dieciséis años podrá solicitar por sí misma ante el Registro Civil la rectificación de la mención registral relativa al sexo.»","Art. 47 Ley 4/2023: «Transcurridos seis meses desde la inscripción en el Registro Civil de la rectificación de la mención registral relativa al sexo, las personas que hubieran promovido dicha rectificación podrán recuperar la mención registral del sexo que figuraba previamente a dicha rectificación en el Registro Civil»","Art. 4.1 RDL 1/2013: «Son personas con discapacidad aquellas que presentan deficiencias físicas, mentales, intelectuales o sensoriales, previsiblemente permanentes que, al interactuar con diversas barreras, puedan impedir su participación plena y efectiva en la sociedad, en igualdad de condiciones con los demás.»","Art. 4.2 RDL 1/2013: «tendrán la consideración de personas con discapacidad aquellas a quienes se les haya reconocido un grado de discapacidad igual o superior al 33 por ciento.»","Art. 42.1 RDL 1/2013: «Las empresas públicas y privadas que empleen a un número de 50 o más trabajadores vendrán obligadas a que de entre ellos, al menos, el 2 por 100 sean trabajadores con discapacidad.»","Art. 2.2 Ley 39/2006: «Situación de dependencia: el estado de carácter permanente en el que las personas, debido a dificultades que afectan a su autonomía, precisan de cuidados y apoyos de otra u otras personas o ayudas importantes para realizar actividades de la vida diaria.»","Art. 26.1 Ley 39/2006: «La situación de dependencia se clasificará en los siguientes grados: a) Grado I. Dependencia moderada […] b) Grado II. Dependencia severa […] c) Grado III. Gran dependencia»","Art. 28.1 Ley 39/2006: «El procedimiento se iniciará a instancia de la persona que pueda estar afectada por algún grado de dependencia o de quien ostente su representación, estableciéndose un plazo máximo de 3 meses para su resolución.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', null, null, null, 'Otras normas citadas: LO 1/2004 (https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760), Ley 4/2023 (https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366), RDL 1/2013 (https://www.boe.es/buscar/act.php?id=BOE-A-2013-12632), Ley 39/2006 (https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990)'
  from public.topics t where t.slug = 'age-aux-b1-16-igualdad'
